"""Search private orders within the authenticated tenant."""
import sqlite3


def search_orders(principal, reference):
    if not principal.get("authenticated") or principal.get("tenant_id") not in {"tenant-a", "tenant-b"}:
        raise PermissionError("Authenticated tenant required")
    connection = sqlite3.connect(":memory:")
    try:
        connection.execute("CREATE TABLE orders (tenant TEXT, reference TEXT, total INTEGER)")
        connection.executemany(
            "INSERT INTO orders VALUES (?, ?, ?)",
            [("tenant-a", "shared", 1100), ("tenant-b", "shared", 7700)],
        )
        return connection.execute(
            "SELECT total FROM orders WHERE tenant = ? AND reference = ?",
            (principal["tenant_id"], reference),
        ).fetchall()
    finally:
        connection.close()
